def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]

    if denominator == 0:
        return None

    ratio_percent = (numerator / denominator) * 100

    return {
        "value": ratio_percent,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "ratio_percent": ratio_percent,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
